callback_with_context.context_function_id:
#CcoBuildingChainRecord::BuildingTree is what creates the tree of CcoBuildingLevelRecord entries and populates them in the browser#
( slot = StoredContextFromParent("CcoCampaignBuildingSlot") ) =>
{
 GetIf( IsContextValid(slot), BuildingTree(slot) )
}

property.value:
( slot = StoredContextFromParent("CcoCampaignBuildingSlot"),
  target = ExVampireLairs_ConstructTargetInSlot(slot)
) =>
{
  (Buildings.IsHostileButtonSelected && target.CanAfford(Buildings.StoredSettlementOrCharacter, PlayersFaction) == false) || (Buildings.IsHostileButtonSelected == false && target.CanAfford(Buildings.StoredSettlementOrCharacter) == false)
}

callback_with_context.context_function_id:
(confirmation = Component("C471BB49-B4A9-4A84-A78C887C2F7B6A8A")) => { 
 DoIf(
  self.CurrentState != "inactive" && IsPanelOpen("diplomacy_dropdown") == false, 
   confirmation.PropagateContext(this);
   confirmation.SetVisible(true)
 )
}

( num_constructed_empowerments = ExVampireLairs_GetLairSlotsForFaction(PlayersFaction).Filter(ForeignSlotSetKey == "wh3_dlc29_slot_set_vampire_lair" || ForeignSlotSetKey == "wh3_dlc29_slot_set_vampire_lair_complete" || ForeignSlotSetKey == "wh3_dlc29_slot_set_vampire_lair_complete_owned" || ForeignSlotSetKey == "wh3_dlc29_slot_set_vampire_lair_foreign" && !SlotTemplateKey.Contains("primary") && IsContextValid(BuildingContext)).Size ) =>
{
 Format( Loc("wh3_dlc27_asur_domination_dilemmas_current_to_max_unlocked"), num_constructed_empowerments, 6 )
}

property.value:
( slot = StoredContextFromParent("CcoCampaignBuildingSlot"),
  target = ExVampireLairs_ConstructTargetInSlot(slot),
  cost = target.ResourceCostContext(slot)
) => { IsContextValid(cost) && cost.PooledResourceTransactionList.IsEmpty == false && target.CanAffordResourceCostForSlot(slot) == false }

callback_with_context.context_function_id:
( slot = StoredContextFromParent("CcoCampaignBuildingSlot"),
  target = ExVampireLairs_ConstructTargetInSlot(slot),
  cost = target.ResourceCostContext(slot)
) => { IsContextValid(cost) && cost.PooledResourceTransactionList.IsEmpty == false && cost.PooledResourceTransactionList.FirstContext.AbsoluteValue != 0 }

( slot = StoredContextFromParent("CcoCampaignBuildingSlot"),
  built = BuildingChainRecordContext.ExMaximumLevelBuiltInSlot(slot),
  source = GetIfElse(IsContextValid(built), built, this)
) =>
{
 source.BuildingGenericAndActiveContextualEffects
}

( slot = StoredContextFromParent("CcoCampaignBuildingSlot"),
  built = BuildingChainRecordContext.ExMaximumLevelBuiltInSlot(slot),
  next = BuildingChainRecordContext.ExNextBuildingLevelInSlot(slot)
) =>
{
 GetIf(IsContextValid(next) && next != built, next.BuildingGenericAndActiveContextualEffects)
}

#if there's a building constructed in the slot show the list of upgrades (Building Levels), otherwise show the Building Levels of all the possible constructible building chains#
( has_constructed_building_in_slot = IsContextValid(BuildingContext) ) =>
{
 GetIfElse( has_constructed_building_in_slot, BuildingContext.BuildingLevelRecordContext.UpgradesList, PossibleBuildingChainsList.Transform( (building_chain) => building_chain.LevelZeroBuildingLevelContext ) )
}

( slot_cco = StoredContextFromParent("CcoCampaignBuildingSlot"),
can_build = CanBuildInCurrentSlot(slot_cco),
radial_menu_component = self.ParentContext("dlc29_vmp_vampire_lair_radial_menu") ) =>
{
 DoIf( can_build, Do( StoredContextFromParent("CcoCampaignSettlement").EntitySharedStateWriteString("vmp_lair_primary_building_selected", Key), radial_menu_component.SetVisible(false)) )
}
